 "contract_type": "nda",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Juniper Cloud Services, Inc."],
   "quote": "between Northwind Labs, Inc., a Delaware corporation (\"NORTHWIND\"), and Juniper Cloud Services, Inc. (\"JUNIPER\")"
  },
  "counterparty": {
   "value": "Juniper Cloud Services, Inc.",
   "quote": "and Juniper Cloud Services, Inc. (\"JUNIPER\")"
  },
  "effective_date": {
   "value": "2025-08-23",
   "quote": "made effective August 23, 2025 (the \"EFFECTIVE DATE\")"
  },
  "term_months": {
   "value": 12,
   "quote": "This AGREEMENT shall remain in effect for twelve (12) months from the EFFECTIVE DATE (the \"TERM\")."
  },
  "auto_renewal": {
   "value": null,
   "quote": null
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Ontario",
   "quote": "The laws of Ontario govern this AGREEMENT and any dispute arising out of or relating to it."
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": null,
   "quote": null
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": 1,
   "quote": "The obligations in this Article 2 shall survive for one (1) year from the date of the relevant disclosure."
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Mateo Rossi",
   "email": "mateo.rossi@juniper.example",
   "title": "Chief Revenue Officer",
   "party": "Juniper Cloud Services, Inc."
  }
 ],
 "risks": [
  {
   "id": "short_confidentiality_survival",
   "severity": "medium",
   "message": "Confidentiality obligations last only one year from each disclosure, so Northwind's trade secrets and other sensitive information may be unprotected soon after. There is no carve-out for trade secrets.",
   "quote": "The obligations in this Article 2 shall survive for one (1) year from the date of the relevant disclosure."
  },
  {
   "id": "incomplete_confidentiality_terms",
   "severity": "medium",
   "message": "The NDA does not define CONFIDENTIAL INFORMATION, set exclusions (public, independently developed, etc.), restrict use to the Purpose, or require return/destruction of materials. Section 2.1 lists only a single obligation, which weakens enforceability.",
   "quote": "(a) hold the DISCLOSING PARTY'S CONFIDENTIAL INFORMATION in strict confidence."
  },
  {
   "id": "non_delaware_governing_law",
   "severity": "low",
   "message": "Governing law is Ontario even though Northwind is a Delaware corporation, which may mean unfamiliar law and a foreign forum for disputes. No forum or venue clause is included.",
   "quote": "The laws of Ontario govern this AGREEMENT and any dispute arising out of or relating to it."
  },
  {
   "id": "non_solicitation_in_nda",
   "severity": "low",
   "message": "A mutual non-solicitation restriction runs for the term plus 12 months, which is unusual in an NDA and limits Northwind's hiring of Juniper personnel involved in the agreement.",
   "quote": "During the TERM and for twelve (12) months thereafter, neither PARTY shall knowingly solicit for employment any PERSONNEL of the other PARTY who were directly involved in performing this AGREEMENT."
  },
  {
   "id": "no_termination_rights",
   "severity": "low",
   "message": "The NDA contains no termination clause, so neither party has an express right to exit before the 12-month term ends. It is also unclear whether the term limits the period in which disclosures may be made.",
   "quote": "This AGREEMENT shall remain in effect for twelve (12) months from the EFFECTIVE DATE (the \"TERM\")."
  },
  {
   "id": "unsigned_and_stale_term",
   "severity": "low",
   "message": "The signature blocks are blank. The 12-month term from 2025-08-23 ended on 2026-08-23, so new disclosures after that date are not covered.",
   "quote": "By: ____________________"
  }
 ],
 "injection_attempt": false,
 "summary": "This is a mutual NDA between Northwind Labs, Inc. and Juniper Cloud Services, Inc. for evaluating a potential business relationship, effective August 23, 2025, with a 12-month term. Confidentiality obligations survive only one year from each disclosure, and the NDA is governed by Ontario law."
}
